INSERT INTO `tbl_rera_master_project_documents` VALUES (6,1001,'Authenticated Copy of Form B','Project Documents','1048576','JPEG/JPG/PDF','readwriteProjectDoc',1,1,0,1,'1','(i)The prescribed format may be downloaded from the Forms and Templates section under the Downloads tab of the web portal. (ii)The Name of the project and promoter must be mentioned in the FORM B. (iii)The Promoter should score out or delete the entries in para 1 and 2 which are not applicable to his case. (iv)A notarized Form-B has to be submitted with the exact date of completion mentioned in dd/MM/yyyy format.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(9,1002,'Pro forma of Allotment Letter to be provided to allottees','Project Documents','1048576','JPEG/JPG/PDF','readwriteProjectDoc',1,1,0,1,'1','(i)Proforma of Allotment Letter to be provided to the allottee at the time of allotment of a particular unit of the project. (ii)No formats have been prescribed for the Allotment letter or the conveyance deed in the Act, Rules or regulations. The promoter has to submit his own formats for allotment letter and conveyance deed as per the type of the project i.e. in case of Plotted, it should be plotted development and in case of built up, it should be for built up development. (iii)Besides providing the formats for Allotment letter and conveyance deed, the promoter has to provide an undertaking that the format they have submitted and will use for these purposes will be in conformity with the RERA Act and Rules.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(10,1003,'Project Schedule or Work Plan','Project Documents','768256','JPEG/JPG/PDF','readwriteProjectDoc',1,1,0,5,'1','The plan of developemt works to be executed in the project and the details of the proposed facilities to be provided thereof and the timelines to achieve the same.','NULL','NULL',2,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(11,1004,'Project Land Photograph','Project Documents','1024096','JPEG/JPG/PDF','readwriteProjectDoc',1,1,0,5,'1','Photograph of Project Land and Construction Site.','NULL','NULL',2,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(13,1005,'Self-Declaration Certification - Potential Zone','Project Documents','512048','JPEG/JPG/PDF','readwriteProjectDoc',1,1,0,1,'1','Self-Declaration from the promoter certifying the Potential Zone under which the project falls.','NULL','NULL',2,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(15,1006,'Pro forma of Conveyance Deed to be signed with allottees','Project Documents','1048576','JPEG/JPG/PDF','readwriteProjectDoc',1,1,0,1,'1','(i)Pro Forma of Conveyance or Sale Deed to be signed with the allottees at the time of registry. (ii)No formats have been prescribed for the conveyance deed in the Act, Rules or regulations. The promoter has to submit his own formats for conveyance deed as per the type of the project i.e. in case of Plotted, it should be plotted development and in case of built up, it should be for built up development. (iii)Besides providing the formats for conveyance deed, the promoter has to provide an undertaking that the format they have submitted, will be used for the purpose in conformity with the RERA Act and Rules.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(16,1007,'Pro forma of Application Form','Project Documents','768256','JPEG/JPG/PDF','readwriteProjectDoc',1,1,0,1,'1','Pro Forma of Application Form','NULL','NULL',2,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(19,1008,'Pro forma Agreement of Sale to be signed with allottees','Project Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',1,3,0,1,'1','(i)Format for agreement for sale as prescribed in the Punjab Real Estate (Regulation and Development) Rules, 2017 shall be applicable to all the projects approved after 01.05.2017. (ii)Format for agreement for sale as prescribed in the Punjab RERA (amended) Rules, 2020 as per Form Q is applicable to all applications received in this Authority on or after 08.10.2020.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(20,1009,'Draft Agreement of Sale highlighting the changes','Project Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',1,2,0,1,'1','Draft Agreement of Sale highlighting the proposed changes in bold and underline where Agreement of Sale is not as per the Annexure A of RERA, Act.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(21,1010,'Approved Layout Plan','Project Land Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',2,1,0,5,'1','(i) Layout Plan of the project land, approved by the competent authority clearly marking the Land Area proposed to be developed and for which RERA Registration is sought. (ii) The area under consent and under ownership should be highlighted clearly. (iii) If the project under consideration is a part of the mega project or any other project, the project area being proposed to be registered should be clearly highlighted. (iv) Submit a clear scan of the area of the layout plan covering all inventories from the approved layout plan. (v) Khasras Numbers should be superimposed on layout plan.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(22,1011,'Land Title Search Report','Project Land Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',2,1,0,1,'1','Land title search report from an advocate having experience of at least ten years.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(24,1012,'Approved Project Site OR Location Map','Project Land Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',2,1,0,1,'1','Approved Site plan or site map or location map of the project showing the location of the project land. Layout plan is mandatory, the site plan may also be submitted in addition to the layout plan if available.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(25,1013,'Sanctioned Building Plan','Project Land Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',2,1,0,1,'1','Sanctioned building plan incase of building/ tower/ group housing/ villas development. In case of plotted development, upload the layout plan. In addition, (i) Submit a clear scan of the area of the building plan covering all inventory. (ii) In case of self-certification scheme please submit the receipts of fee deposited.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(26,1014,'Details of Encumbrances over the land','Project Land Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',2,3,0,1,'1','Upload Details of Land Encumbrances - Details of charge created on the land or building in any manner by the promoter or any other authority as on the date of application of Project Registration. Any Encumbrance even if not recorded in the revenue record should be declared. The Non Encumbrance certificate should relate to the period when the application for registration of the project is filed before the Authority.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(28,1015,'Non Encumbrance Certificate','Project Land Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',2,2,0,1,'1','Any Encumbrance even if not recorded in the revenue record should be declared. The Non Encumbrance certificate should relate to the period when the application for registration of the project is filed before the Authority.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(29,1016,'Commencement Certificate (Mega Project Category)','Project Approval Details','3145728','JPEG/JPG/PDF','readwriteProjectDoc',3,1,0,1,'1','Commencement Certificate i.e. Agreement between Promoter and the concerned development authority (Mega Project Category).','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(30,1017,'Copy of Registration as Promoter','Project Approval Details','1048576','JPEG/JPG/PDF','readwriteProjectDoc',3,2,0,1,'1','(i)Govt. entities are exempted. In case of sites allotted by GMADA, GLADA, ADA, JDA, etc. in open auction or otherwise, Promoter registration is exempted as the PAPRA is not applicable in such cases. (ii)In case of unauthorized colonies, Regularization Certificate issued by the Competent Authority shall be treated as a Promoter Registration if the regularization certificate is issued in the name of the Promoter. In case the regularization certificate issued is not in the name of the promoter applying for registration of the project, then the promoter will be required to submit copy of Promoter Registration Certificate. (iii)The certificate of registration as promoter is required to be submitted by the promoter in cases where area of the project for which registration is applied falls under mega project.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(31,1018,'CLU Certificate','Project Approval Details','5242880','JPEG/JPG/PDF','readwriteProjectDoc',3,2,0,5,'1','In the case of unauthorized colonies, Regularization Certificate issued by the Competent Authority shall be treated as a CLU Certificate.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(32,1019,'License to develop colony or society from Competent Authority','Project Approval Details','1048576','JPEG/JPG/PDF','readwriteProjectDoc',3,2,0,1,'1','(i)Valid license or Application for the renewal of License to develop colony or society from the Competent Authority. (ii)In case of mega project, agreement signed between the state government and promoter shall be provided which is considered as commencement certificate. If expired, copy of application applied for renewal of the same along with receipt of fees should be provided. (iii)If license to develop colony issued under PAPRA has expired, then provide copy of application applied for renewal of the license along with receipt of fees paid to the Competent Authority. (iv)In case of unauthorized colonies, Regularization Certificate issued by the Competent Authority shall be treated as the license to develop colony, and is to be uploaded with all annexures. If provisional regularization certificate has expired, then to provide final regularization certificate issued by the Competent Authority. (v)Copy of final notification printed in gazette in case of TP Scheme and in case of land of Improvement Trusts.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(33,1020,'Legal Title Deed(s) - In case Land is owned by Promoter','Project Land Documents','31457280','JPEG/JPG/PDF','readwriteProjectDoc',4,2,0,10,'1','(i)Authenticated copy of the legal title deed through which land is acquired, reflecting the title of the promoter to the land on which development of project is proposed. (ii)Upload any Document from Sale Deed / Gift Deed / Exchange Deed / Inheritance / Court Decree / Other. (iii)The land details submitted should match the official records being submitted and title deed for the land not owned. (iv)Where the land is inherited copy of the relevant jamabandi is required.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(36,1021,'Latest Jamabandi Document','Project Land Documents','31457280','JPEG/JPG/PDF','readwriteProjectDoc',4,2,0,5,'1','Latest jamabandi of the project land, should relate to period when the application for registration is submitted to Authority.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(37,1022,'Consent details of actual owner of Land','Project Land Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',4,3,0,10,'1','Upload - Consent Details of Land Owner in case land is not owned by promoter. Should be accompanied in the form of the collaboration agreement, joint agreement or any other agreement between the promoters and other land owners whereby the right to sell is granted to the promoter explicitly by all the land owners. Consent/NOC to become promoter, of the land owners is essential.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(40,1023,'Collaboration or Joint Development Agreement','Project Land Documents','5242880','JPEG/JPG/PDF','readwriteProjectDoc',4,3,0,10,'1','(i)Copy of collaboration agreement, development agreement, joint development agreement or any other agreement entered between promoter and actual land owner(s) in case land is not owned by promoter. (ii)Registration shall be granted strictly as per the sanctioned layout plan and for the area owned by the promoter, if the consent or JDA is not granted.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(42,1024,'Land Title Deed(s) - In case land is not owned by Promoter','Project Land Documents','31457280','JPEG/JPG/PDF','readwriteProjectDoc',4,3,0,10,'1','Legal title deed of the original owner(s) of the part of the project land not owned by promoter.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(44,1025,'Architects Certificate (Form 1)','Project Documents','1048576','PDF','readwriteProjectDoc',5,2,0,1,'1','Architect\'s Certificate as per the Form 1 of the RERA Punjab General Regulations is required to be submitted for all on going project. The prescribed format may be downloaded from the Forms & Templates section under the Downloads tab of the web portal.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(45,1026,'Engineers Certificate (Form 2)','Project Documents','1048576','PDF','readwriteProjectDoc',5,2,0,1,'1','Engineer\'s Certificate as per the Form 2 of the RERA Punjab General Regulations is required to be submitted for all on going project. The prescribed format may be downloaded from the Forms and Templates section under the Downloads tab of the web portal.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(46,1027,'CA Certificate (Form 3)','Project Documents','1048576','PDF','readwriteProjectDoc',5,1,0,1,'1','(i)It is mandatory to mention UDIN of the CA on document certified by Chartered Accountant. (ii)In case of on-going projects following certificates along with CA certificate are also required to be submitted, (a)Architect Certificate Form 1 see regulation 3. (b)Engineer Certificate Form 2 see regulation 3. (iii)The prescribed format may be downloaded from the Forms & Templates section under the Downloads tab of the web portal.','NULL','NULL',1,'systemdb','2024-11-17 13:08:00.000','systemdb','2024-11-17 13:08:00.000'),(47,1028,'Project Land Khasra Report or Plan','Project Land Documents','1048576','PDF','readwriteProjectDoc',5,1,0,5,'1','(i)Khasra details of the project land consisting of a) Khasra Number b) Area of land proposed to be developed under the khasra no. c) Name of the village under the khasra no. d) ownership status-Not Owned By Promoter/Owned By Promoter. (ii)Upload a PDF of khasra plan containing khasra numbers in the project under the project land khasra report.',NULL,NULL,1,'sysadmin','2018-11-17 13:08:00.000','sysadmin','2018-11-17 13:08:00.000'),(48,1029,'Declaration for AFS, CD and Allottment Letter','Project Approvals','1048576','PDF','readwriteProjectDoc',5,1,0,1,'1','Declaration stating that the clauses mentioned in Conveyance Deed and Allotment Letter are in conformity with the Agreement of Sale as per RERA Act/Rules.',NULL,NULL,1,'sysadmin','2018-11-17 13:08:00.000','sysadmin','2018-11-17 13:08:00.000'),(49,1030,'Proforma for Undertaking- cum-Indemnity Bond','Project Documents','1048576','PDF','readwriteProjectDoc',5,1,0,1,'1','Proforma for Undertaking- cum-Indemnity Bond with regard to GST alongwith late fees interest.',NULL,NULL,1,'sysadmin','2022-10-13 10:10:00.000','sysadmin','2022-10-13 10:10:00.000');
